+static void
+update_service_name_fields(void)
+{
+    /* deregister old dynamic service name fields if they exist */
+    if (data_someip_service_hfs)
+    {
+        deregister_dynamic_hf_data(&dynamic_hf_service_names, &dynamic_hf_service_names_size);
+        g_hash_table_destroy(data_someip_service_hfs);
+        data_someip_service_hfs = NULL;
+    }
+
+    /* create dynamic service name fields if enabled */
+    if (someip_service_name_fields_explicit && someip_service_ident_num > 0)
+    {
+        allocate_dynamic_hf_data(&dynamic_hf_service_names, &dynamic_hf_service_names_size, someip_service_ident_num);
+        data_someip_service_hfs = g_hash_table_new_full(g_direct_hash, g_direct_equal, NULL, NULL);
+
+        for (unsigned i = 0; i < someip_service_ident_num; i++)
+        {
+            int *hf_id = g_new(int, 1);
+            *hf_id = -1;
+
+            /* Create filter name: someip.service.<servicename> */
+            char *filter_name = ws_strdup_printf("someip.service.%s", someip_service_ident[i].name);
+            char *field_name = ws_strdup_printf("Service Name (%s)", someip_service_ident[i].name);
+
+            dynamic_hf_service_names[i].p_id = hf_id;
+            dynamic_hf_service_names[i].hfinfo.name = field_name;
+            dynamic_hf_service_names[i].hfinfo.abbrev = filter_name;
+            dynamic_hf_service_names[i].hfinfo.type = FT_STRING;
+            dynamic_hf_service_names[i].hfinfo.display = BASE_NONE;
+            dynamic_hf_service_names[i].hfinfo.strings = NULL;
+            dynamic_hf_service_names[i].hfinfo.bitmask = 0x0;
+            dynamic_hf_service_names[i].hfinfo.blurb = NULL;
+            dynamic_hf_service_names[i].hfinfo.id = -1;
+            dynamic_hf_service_names[i].hfinfo.parent = 0;
+            dynamic_hf_service_names[i].hfinfo.ref_type = HF_REF_TYPE_NONE;
+            dynamic_hf_service_names[i].hfinfo.same_name_prev_id = -1;
+            dynamic_hf_service_names[i].hfinfo.same_name_next = NULL;
+
+            g_hash_table_insert(data_someip_service_hfs, GUINT_TO_POINTER(someip_service_ident[i].id), hf_id);
+        }
+
+        proto_register_field_array(proto_someip, dynamic_hf_service_names, dynamic_hf_service_names_size);
+    }
+}
+
+static void
+update_service_method_fields(void)
+{
+    /* deregister old dynamic service+method name fields if they exist */
+    if (data_someip_service_method_hfs)
+    {
+        deregister_dynamic_hf_data(&dynamic_hf_service_method_names, &dynamic_hf_service_method_names_size);
+        g_hash_table_destroy(data_someip_service_method_hfs);
+        data_someip_service_method_hfs = NULL;
+    }
+
+    /* create dynamic service+method name fields if enabled */
+    if (someip_service_name_fields_explicit && someip_method_ident_num > 0)
+    {
+        allocate_dynamic_hf_data(&dynamic_hf_service_method_names, &dynamic_hf_service_method_names_size, someip_method_ident_num);
+        data_someip_service_method_hfs = g_hash_table_new_full(g_direct_hash, g_direct_equal, NULL, NULL);
+
+        for (unsigned i = 0; i < someip_method_ident_num; i++)
+        {
+            int *hf_id = g_new(int, 1);
+            *hf_id = -1;
+
+            /* Get service name for this method */
+            char *service_name = someip_lookup_service_name(someip_method_ident[i].id);
+            if (service_name != NULL)
+            {
+                /* Create filter name: someip.method.<servicename>.<methodname> */
+                char *filter_name = ws_strdup_printf("someip.method.%s.%s", service_name, someip_method_ident[i].name);
+                char *field_name = ws_strdup_printf("Service+Method Name (%s.%s)", service_name, someip_method_ident[i].name);
+
+                dynamic_hf_service_method_names[i].p_id = hf_id;
+                dynamic_hf_service_method_names[i].hfinfo.name = field_name;
+                dynamic_hf_service_method_names[i].hfinfo.abbrev = filter_name;
+                dynamic_hf_service_method_names[i].hfinfo.type = FT_STRING;
+                dynamic_hf_service_method_names[i].hfinfo.display = BASE_NONE;
+                dynamic_hf_service_method_names[i].hfinfo.strings = NULL;
+                dynamic_hf_service_method_names[i].hfinfo.bitmask = 0x0;
+                dynamic_hf_service_method_names[i].hfinfo.blurb = NULL;
+                dynamic_hf_service_method_names[i].hfinfo.id = -1;
+                dynamic_hf_service_method_names[i].hfinfo.parent = 0;
+                dynamic_hf_service_method_names[i].hfinfo.ref_type = HF_REF_TYPE_NONE;
+                dynamic_hf_service_method_names[i].hfinfo.same_name_prev_id = -1;
+                dynamic_hf_service_method_names[i].hfinfo.same_name_next = NULL;
+
+                uint32_t key = (((uint32_t)someip_method_ident[i].id & 0xffff) << 16) | ((uint32_t)someip_method_ident[i].id2 & 0xffff);
+                g_hash_table_insert(data_someip_service_method_hfs, GUINT_TO_POINTER(key), hf_id);
+            }
+        }
+
+        proto_register_field_array(proto_someip, dynamic_hf_service_method_names, dynamic_hf_service_method_names_size);
+    }
 }

